tool_use_result.content:
/* ChartPulse — Trading Terminal Design System */
:root {
  --bg-0: #0a0a0f;
  --bg-1: #0f0f1a;
  --bg-2: #14142a;
  --bg-3: #1a1a2e;
  --bg-4: #1f1f38;
  --surface: #16162b;
  --surface-2: #1c1c34;
  --border: #252544;
  --border-strong: #33335a;
  --text-0: #f5f6ff;
  --text-1: #d6d8ee;
  --text-2: #9da0c2;
  --text-3: #6c6e8f;
  --accent: #2962FF;
  --accent-2: #4d7fff;
  --accent-soft: rgba(41, 98, 255, 0.12);
  --green: #22ab94;
  --green-bright: #26d4a8;
  --green-soft: rgba(38, 212, 168, 0.12);
  --red: #F7525F;
  --red-bright: #ff6b78;
  --red-soft: rgba(247, 82, 95, 0.12);
  --amber: #ffb547;
  --purple: #b18bff;
  --teal: #00c6c6;
  --gold: #d4a72c;
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 12px 40px rgba(0, 0, 0, 0.6);
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-xl: 14px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace;
  --header-h: 56px;
  --subnav-h: 44px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg-0);
  color: var(--text-1);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'cv11', 'ss01';
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input, select { font-family: inherit; }

/* Numerics — tabular for tables */
.num, td.num, .price, .change {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum';
}

/* ====== Header / Top Nav ====== */
.app-header {
  position: sticky;
  top: 0;
  z-index: 50;
  height: var(--header-h);
  background: rgba(15, 15, 26, 0.92);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 20px;
  gap: 24px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 700;
  font-size: 16px;
  color: var(--text-0);
  letter-spacing: -0.01em;
}
.logo-mark {
  width: 26px;
  height: 26px;
  background: linear-gradient(135deg, var(--accent), var(--teal));
  border-radius: 7px;
  display: grid;
  place-items: center;
  color: white;
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.main-nav a {
  padding: 8px 13px;
  border-radius: 6px;
  color: var(--text-2);
  font-weight: 500;
  font-size: 13.5px;
  transition: all .15s;
}
.main-nav a:hover { color: var(--text-0); background: var(--surface); }
.main-nav a.active { color: var(--text-0); background: var(--surface); }
.header-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 10px;
  width: 240px;
  color: var(--text-3);
  font-size: 13px;
}
.header-search input {
  background: none;
  border: none;
  color: var(--text-0);
  outline: none;
  flex: 1;
  font-size: 13px;
}
.header-actions { display: flex; align-items: center; gap: 8px; }
.btn-icon {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  transition: all .15s;
}
.btn-icon:hover { background: var(--surface); color: var(--text-0); }

/* ====== Buttons ====== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  transition: all .15s;
  border: 1px solid transparent;
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: white;
}
.btn-primary:hover { background: var(--accent-2); }
.btn-secondary {
  background: var(--surface);
  color: var(--text-0);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--surface-2); border-color: var(--accent); }
.btn-ghost { color: var(--text-1); }
.btn-ghost:hover { background: var(--surface); }
.btn-lg { padding: 12px 22px; font-size: 14px; }
.btn-sm { padding: 6px 11px; font-size: 12px; border-radius: 5px; }

/* ====== Common Layout ====== */
.container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}
.container-wide { max-width: 1600px; margin: 0 auto; padding: 0 20px; }

/* ====== Tabs / Pills ====== */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--surface);
  padding: 3px;
  border-radius: 7px;
  border: 1px solid var(--border);
}
.tab {
  padding: 6px 13px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-2);
  border-radius: 5px;
  transition: all .15s;
  white-space: nowrap;
}
.tab:hover { color: var(--text-0); }
.tab.active {
  background: var(--bg-3);
  color: var(--text-0);
  box-shadow: 0 1px 2px rgba(0,0,0,.3);
}

.tab-line {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  scrollbar-width: none;
}
.tab-line::-webkit-scrollbar { display: none; }
.tab-line .tab-l {
  padding: 11px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-2);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  cursor: pointer;
  white-space: nowrap;
  transition: all .15s;
}
.tab-line .tab-l:hover { color: var(--text-0); }
.tab-line .tab-l.active {
  color: var(--text-0);
  border-color: var(--accent);
}

/* ====== Badges & Chips ====== */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.badge-up { color: var(--green-bright); background: var(--green-soft); }
.badge-down { color: var(--red-bright); background: var(--red-soft); }
.badge-neutral { color: var(--text-2); background: var(--surface); }
.badge-platinum { color: #d6e4ff; background: linear-gradient(135deg, #2e3a52, #1a2238); border: 1px solid #3a4a6a; }
.badge-gold { color: #2a1f00; background: linear-gradient(135deg, #f5c84c, #c89427); }
.badge-tier {
  padding: 4px 10px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.up { color: var(--green-bright); }
.down { color: var(--red-bright); }

/* ====== Cards & Sections ====== */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 18px;
}
.section { padding: 40px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 18px;
  gap: 16px;
  flex-wrap: wrap;
}
.section-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-0);
}
.section-sub { color: var(--text-2); font-size: 13px; margin-top: 4px; }

/* ====== Tables ====== */
.tbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.tbl th {
  text-align: left;
  font-weight: 500;
  color: var(--text-3);
  font-size: 11.5px;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}
.tbl td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-1);
}
.tbl tr:hover td { background: rgba(255,255,255,.025); }
.tbl td.num, .tbl th.num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl tbody tr:last-child td { border-bottom: none; }

.t-symbol {
  display: flex; align-items: center; gap: 10px;
  font-weight: 600;
}
.t-icon {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--bg-3);
  display: grid; place-items: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-0);
  flex-shrink: 0;
  border: 1px solid var(--border);
}
.t-icon.bg-blue { background: linear-gradient(135deg, #2962FF, #4d7fff); border: none; color: #fff; }
.t-icon.bg-green { background: linear-gradient(135deg, #00d4a8, #00b394); border: none; color: #001712; }
.t-icon.bg-red { background: linear-gradient(135deg, #ff6b78, #d63f4d); border: none; color: #fff; }
.t-icon.bg-orange { background: linear-gradient(135deg, #ff9d3a, #f57c00); border: none; color: #fff; }
.t-icon.bg-purple { background: linear-gradient(135deg, #b18bff, #7c5cff); border: none; color: #fff; }
.t-icon.bg-gold { background: linear-gradient(135deg, #f5c84c, #c89427); border: none; color: #2a1f00; }
.t-icon.bg-teal { background: linear-gradient(135deg, #00c6c6, #008b8b); border: none; color: #fff; }
.t-icon.bg-pink { background: linear-gradient(135deg, #f06292, #c94570); border: none; color: #fff; }

.t-meta { display: flex; flex-direction: column; }
.t-meta .t-name { font-size: 11.5px; color: var(--text-3); font-weight: 400; }

/* ====== Sparklines ====== */
.spark { width: 88px; height: 28px; display: inline-block; vertical-align: middle; }
.spark-up path.line { stroke: var(--green-bright); }
.spark-up path.fill { fill: url(#gradUp); }
.spark-down path.line { stroke: var(--red-bright); }
.spark-down path.fill { fill: url(#gradDown); }

/* ====== Hero ====== */
.hero {
  position: relative;
  padding: 80px 0 60px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 20% 0%, rgba(41,98,255,.18), transparent 50%),
    radial-gradient(ellipse at 80% 30%, rgba(0,198,198,.12), transparent 50%),
    var(--bg-0);
}
.hero::before {
  content: "";
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 60px 60px;
  mask: radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%);
  -webkit-mask: radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%);
  pointer-events: none;
}
.hero-inner { position: relative; display: grid; grid-template-columns: 1.1fr 1fr; gap: 50px; align-items: center; }
.hero h1 {
  font-size: 56px;
  line-height: 1.04;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--text-0);
  margin-bottom: 18px;
}
.hero h1 .accent {
  background: linear-gradient(120deg, var(--accent-2), var(--teal));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p.lead {
  font-size: 17px;
  color: var(--text-2);
  max-width: 560px;
  margin-bottom: 28px;
  line-height: 1.6;
}
.hero-ctas { display: flex; gap: 12px; margin-bottom: 26px; }
.hero-meta { display: flex; gap: 28px; color: var(--text-3); font-size: 13px; }
.hero-meta strong { color: var(--text-0); font-weight: 600; }
.hero-visual {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 4/3;
}
.hv-toolbar {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-2);
}
.hv-toolbar .price { font-size: 22px; font-weight: 700; color: var(--text-0); }
.hv-chart { height: calc(100% - 50px); position: relative; }

/* ====== Footer ====== */
.footer {
  background: var(--bg-1);
  border-top: 1px solid var(--border);
  padding: 50px 0 28px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-0);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 14px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 9px; }
.footer-col a {
  color: var(--text-2);
  font-size: 13px;
  transition: color .15s;
}
.footer-col a:hover { color: var(--text-0); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-3);
  font-size: 12px;
  flex-wrap: wrap;
  gap: 12px;
}

/* ====== Market Summary (home) ====== */
.summary-bar {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  overflow: hidden;
}
.summary-cell {
  padding: 14px 16px;
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.summary-cell:last-child { border-right: none; }
.summary-cell .label {
  font-size: 12px;
  color: var(--text-3);
  font-weight: 500;
}
.summary-cell .value {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-0);
  font-variant-numeric: tabular-nums;
}

/* ====== Idea Cards ====== */
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.idea-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all .2s;
  display: flex;
  flex-direction: column;
}
.idea-card:hover { transform: translateY(-2px); border-color: var(--border-strong); box-shadow: var(--shadow-md); }
.idea-thumb {
  aspect-ratio: 16/10;
  position: relative;
  background: var(--bg-2);
  overflow: hidden;
}
.idea-thumb svg { width: 100%; height: 100%; display: block; }
.idea-thumb .badge-bias {
  position: absolute; top: 10px; left: 10px;
  font-size: 10.5px;
  padding: 3px 8px;
  letter-spacing: .04em;
}
.idea-thumb .ticker-tag {
  position: absolute; top: 10px; right: 10px;
  background: rgba(0,0,0,.6);
  backdrop-filter: blur(8px);
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-0);
}
.idea-body { padding: 14px 14px 12px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.idea-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-0);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.idea-author {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px;
  color: var(--text-2);
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.avatar {
  width: 22px; height: 22px;
  border-radius: 50%;
  background: var(--accent);
  display: grid; place-items: center;
  font-size: 10px;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}
.idea-stats {
  display: flex; gap: 12px;
  font-size: 11.5px;
  color: var(--text-3);
}

/* ====== Chart page ====== */
.chart-app {
  display: grid;
  grid-template-columns: 56px 1fr 320px;
  height: calc(100vh - var(--header-h));
}
.chart-tools {
  background: var(--bg-1);
  border-right: 1px solid var(--border);
  padding: 8px 0;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.tool-btn {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  transition: all .15s;
}
.tool-btn:hover { background: var(--surface); color: var(--text-0); }
.tool-btn.active { background: var(--accent-soft); color: var(--accent-2); }
.tool-divider { width: 24px; height: 1px; background: var(--border); margin: 6px 0; }

.chart-main { display: flex; flex-direction: column; min-width: 0; background: var(--bg-1); }
.chart-toolbar {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-1);
  flex-wrap: wrap;
}
.symbol-picker {
  display: flex; align-items: center; gap: 10px;
  padding: 6px 12px;
  border-radius: 6px;
  background: var(--surface);
  border: 1px solid var(--border);
  cursor: pointer;
}
.symbol-picker:hover { border-color: var(--border-strong); }
.symbol-picker .sym {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-0);
}
.tf-group { display: flex; gap: 1px; background: var(--surface); border: 1px solid var(--border); border-radius: 5px; padding: 1px; }
.tf-btn {
  padding: 5px 10px;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-2);
  border-radius: 4px;
  font-variant-numeric: tabular-nums;
}
.tf-btn:hover { color: var(--text-0); }
.tf-btn.active { background: var(--accent); color: white; }
.toolbar-divider { width: 1px; height: 22px; background: var(--border); }

.chart-canvas { flex: 1; position: relative; min-height: 360px; background: var(--bg-1); }
.chart-svg { width: 100%; height: 100%; display: block; }

.chart-bottom {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid var(--border);
  background: var(--bg-1);
  max-height: 320px;
  overflow: hidden;
}
.detail-block {
  padding: 16px 18px;
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.detail-block:last-child { border-right: none; }

.watchlist-side {
  background: var(--bg-1);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.wl-head {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
  font-size: 12px;
  color: var(--text-2);
  font-weight: 600;
}
.wl-content { flex: 1; overflow-y: auto; }
.wl-cat {
  border-bottom: 1px solid var(--border);
}
.wl-cat-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 9px 12px;
  background: var(--bg-2);
  cursor: pointer;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-2);
  text-transform: uppercase;
  letter-spacing: .04em;
  user-select: none;
}
.wl-cat-head .chev { transition: transform .2s; }
.wl-cat.open .wl-cat-head .chev { transform: rotate(90deg); }
.wl-cat-body { display: none; }
.wl-cat.open .wl-cat-body { display: block; }
.wl-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  font-size: 12.5px;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.wl-row:hover { background: rgba(255,255,255,.03); }
.wl-row .sym { font-weight: 600; color: var(--text-0); }
.wl-row .last { color: var(--text-1); text-align: right; }
.wl-row .chg { font-size: 11.5px; font-weight: 600; text-align: right; min-width: 56px; }

/* ====== Stat grid ====== */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 12px;
}
.stat-tile {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 12px;
}
.stat-tile .label { font-size: 11.5px; color: var(--text-3); }
.stat-tile .val { font-size: 16px; font-weight: 700; color: var(--text-0); margin-top: 4px; font-variant-numeric: tabular-nums; }
.stat-tile .sub { font-size: 11px; color: var(--text-2); margin-top: 2px; }

/* ====== Markets page sections ====== */
.markets-tabs {
  position: sticky;
  top: var(--header-h);
  z-index: 30;
  background: var(--bg-0);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
}

.market-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
}
.movers-list { display: flex; flex-direction: column; gap: 8px; }
.mover-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 12px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 7px;
}
.mover-row .name { font-size: 13px; font-weight: 500; color: var(--text-0); }
.mover-row .sub { font-size: 11.5px; color: var(--text-3); }

/* ====== Brokers ====== */
.broker-card {
  display: grid;
  grid-template-columns: 200px 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 20px 22px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 12px;
  transition: all .15s;
}
.broker-card:hover { border-color: var(--border-strong); transform: translateY(-1px); }
.broker-brand { display: flex; align-items: center; gap: 14px; }
.broker-logo {
  width: 50px; height: 50px;
  border-radius: 9px;
  display: grid; place-items: center;
  font-size: 14px;
  font-weight: 800;
  color: #fff;
  flex-shrink: 0;
}
.broker-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-0);
}
.broker-details {
  display: flex;
  align-items: center;
  gap: 28px;
}
.broker-stat .label { font-size: 11px; color: var(--text-3); text-transform: uppercase; letter-spacing: .04em; }
.broker-stat .val { font-size: 14px; font-weight: 600; color: var(--text-0); margin-top: 2px; }
.broker-rating { display: flex; align-items: center; gap: 8px; }
.rating-num {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-0);
  line-height: 1;
}
.rating-stars { color: var(--gold); font-size: 12px; letter-spacing: 1px; }
.broker-promo {
  background: var(--accent-soft);
  color: var(--accent-2);
  padding: 5px 10px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
  border: 1px solid rgba(41,98,255,.25);
}

/* ====== Stats banner ====== */
.stats-banner {
  background: linear-gradient(120deg, var(--bg-2), var(--bg-3));
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 36px 40px;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 30px;
  margin: 32px 0;
}
.stat-big .num { font-size: 46px; font-weight: 800; color: var(--text-0); letter-spacing: -.02em; line-height: 1; }
.stat-big .num .accent-blue { color: var(--accent-2); }
.stat-big .label { font-size: 13px; color: var(--text-2); margin-top: 8px; }

/* ====== Generic flex utilities ====== */
.row { display: flex; align-items: center; gap: 8px; }
.between { justify-content: space-between; }
.gap-12 { gap: 12px; } .gap-16 { gap: 16px; } .gap-20 { gap: 20px; }
.flex-1 { flex: 1; }
.muted { color: var(--text-3); }
.txt-0 { color: var(--text-0); }
.txt-1 { color: var(--text-1); }
.txt-2 { color: var(--text-2); }
.fw-7 { font-weight: 700; }
.fs-12 { font-size: 12px; } .fs-13 { font-size: 13px; } .fs-14 { font-size: 14px; }
.mt-8 { margin-top: 8px; } .mt-12 { margin-top: 12px; } .mt-16 { margin-top: 16px; } .mt-24 { margin-top: 24px; }
.mb-12 { margin-bottom: 12px; } .mb-16 { margin-bottom: 16px; } .mb-24 { margin-bottom: 24px; }

/* ====== Page hero (smaller) ====== */
.page-hero {
  padding: 50px 0 30px;
  background:
    radial-gradient(ellipse at 30% 0%, rgba(41,98,255,.18), transparent 60%),
    var(--bg-0);
  border-bottom: 1px solid var(--border);
}
.page-hero h1 {
  font-size: 38px;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--text-0);
  margin-bottom: 8px;
}
.page-hero p { color: var(--text-2); font-size: 15px; max-width: 640px; }

/* ====== Pagination ====== */
.pager {
  display: flex; justify-content: center; gap: 6px; margin: 32px 0;
}
.pager button {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 600;
  border: 1px solid var(--border);
  background: var(--surface);
}
.pager button:hover { color: var(--text-0); border-color: var(--border-strong); }
.pager button.active { background: var(--accent); color: white; border-color: var(--accent); }

/* ====== Trending list ====== */
.trending-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.trend-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px;
  display: flex; flex-direction: column; gap: 8px;
  transition: all .15s;
}
.trend-card:hover { border-color: var(--border-strong); }
.trend-head { display: flex; align-items: center; justify-content: space-between; }
.trend-card .price { font-size: 18px; font-weight: 700; color: var(--text-0); font-variant-numeric: tabular-nums; }

/* ====== Indicator/strategy cards ====== */
.ind-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.ind-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
  display: flex; gap: 12px;
}
.ind-icon {
  width: 40px; height: 40px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent-2);
  display: grid; place-items: center;
  flex-shrink: 0;
}
.ind-card h4 { font-size: 14px; font-weight: 600; color: var(--text-0); margin-bottom: 3px; }
.ind-card p { font-size: 12px; color: var(--text-2); line-height: 1.5; }

/* ====== Stories ====== */
.stories-grid { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 16px; }
.story-feature {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  min-height: 360px;
  display: flex; flex-direction: column;
}
.story-feature .sf-img { aspect-ratio: 16/9; background: linear-gradient(135deg, #1a3354, #2a1a4d); }
.story-feature .sf-body { padding: 18px; flex: 1; display: flex; flex-direction: column; gap: 10px; }
.story-feature h3 { font-size: 19px; font-weight: 700; color: var(--text-0); line-height: 1.25; }
.story-side {
  display: flex; flex-direction: column; gap: 12px;
}
.story-row {
  display: flex; gap: 10px;
  padding: 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.story-row .sr-img {
  width: 80px; height: 64px;
  border-radius: 6px;
  flex-shrink: 0;
  background: var(--bg-3);
}
.story-row h5 { font-size: 13px; color: var(--text-0); font-weight: 600; line-height: 1.3; }
.story-row .meta { font-size: 11px; color: var(--text-3); margin-top: 4px; }

/* ====== Mini chart styles ====== */
.mini-chart-cell {
  display: flex; align-items: center; gap: 6px;
}

/* ====== Stocks tabs row ====== */
.stocks-flex {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 16px;
}

/* Responsive */
@media (max-width: 1280px) {
  .summary-bar { grid-template-columns: repeat(3, 1fr); }
  .summary-cell:nth-child(3) { border-right: none; }
  .ideas-grid { grid-template-columns: repeat(3, 1fr); }
  .ind-grid { grid-template-columns: repeat(2, 1fr); }
  .trending-list { grid-template-columns: repeat(3, 1fr); }
  .stocks-flex { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1.2fr repeat(3, 1fr); }
  .chart-app { grid-template-columns: 56px 1fr 280px; }
}
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero h1 { font-size: 40px; }
  .ideas-grid, .trending-list { grid-template-columns: repeat(2, 1fr); }
  .stories-grid { grid-template-columns: 1fr; }
  .stats-banner { grid-template-columns: 1fr; gap: 20px; }
  .header-search { display: none; }
  .main-nav { gap: 0; overflow-x: auto; }
  .ind-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .stocks-flex { grid-template-columns: 1fr; }
  .market-grid { grid-template-columns: 1fr; }
  .broker-card { grid-template-columns: 1fr; gap: 14px; }
  .chart-app { grid-template-columns: 1fr; }
  .chart-tools, .watchlist-side { display: none; }
}
@media (max-width: 640px) {
  .hero h1 { font-size: 30px; }
  .summary-bar { grid-template-columns: 1fr 1fr; }
  .ideas-grid, .trending-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .container { padding: 0 14px; }
  .section { padding: 28px 0; }
}

/* ChartPulse — Trading Terminal Design System */
:root {
  --bg-0: #0a0a0f;
  --bg-1: #0f0f1a;
  --bg-2: #14142a;
  --bg-3: #1a1a2e;
  --bg-4: #1f1f38;
  --surface: #16162b;
  --surface-2: #1c1c34;
  --border: #252544;
  --border-strong: #33335a;
  --text-0: #f5f6ff;
  --text-1: #d6d8ee;
  --text-2: #9da0c2;
  --text-3: #6c6e8f;
  --accent: #2962FF;
  --accent-2: #4d7fff;
  --accent-soft: rgba(41, 98, 255, 0.12);
  --green: #22ab94;
  --green-bright: #26d4a8;
  --green-soft: rgba(38, 212, 168, 0.12);
  --red: #F7525F;
  --red-bright: #ff6b78;
  --red-soft: rgba(247, 82, 95, 0.12);
  --amber: #ffb547;
  --purple: #b18bff;
  --teal: #00c6c6;
  --gold: #d4a72c;
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 12px 40px rgba(0, 0, 0, 0.6);
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-xl: 14px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace;
  --header-h: 56px;
  --subnav-h: 44px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg-0);
  color: var(--text-1);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'cv11', 'ss01';
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input, select { font-family: inherit; }

/* Numerics — tabular for tables */
.num, td.num, .price, .change {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum';
}

/* ====== Header / Top Nav ====== */
.app-header {
  position: sticky;
  top: 0;
  z-index: 50;
  height: var(--header-h);
  background: rgba(15, 15, 26, 0.92);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 20px;
  gap: 24px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 700;
  font-size: 16px;
  color: var(--text-0);
  letter-spacing: -0.01em;
}
.logo-mark {
  width: 26px;
  height: 26px;
  background: linear-gradient(135deg, var(--accent), var(--teal));
  border-radius: 7px;
  display: grid;
  place-items: center;
  color: white;
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.main-nav a {
  padding: 8px 13px;
  border-radius: 6px;
  color: var(--text-2);
  font-weight: 500;
  font-size: 13.5px;
  transition: all .15s;
}
.main-nav a:hover { color: var(--text-0); background: var(--surface); }
.main-nav a.active { color: var(--text-0); background: var(--surface); }
.header-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 10px;
  width: 240px;
  color: var(--text-3);
  font-size: 13px;
}
.header-search input {
  background: none;
  border: none;
  color: var(--text-0);
  outline: none;
  flex: 1;
  font-size: 13px;
}
.header-actions { display: flex; align-items: center; gap: 8px; }
.btn-icon {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  transition: all .15s;
}
.btn-icon:hover { background: var(--surface); color: var(--text-0); }

/* ====== Buttons ====== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  transition: all .15s;
  border: 1px solid transparent;
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: white;
}
.btn-primary:hover { background: var(--accent-2); }
.btn-secondary {
  background: var(--surface);
  color: var(--text-0);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--surface-2); border-color: var(--accent); }
.btn-ghost { color: var(--text-1); }
.btn-ghost:hover { background: var(--surface); }
.btn-lg { padding: 12px 22px; font-size: 14px; }
.btn-sm { padding: 6px 11px; font-size: 12px; border-radius: 5px; }

/* ====== Common Layout ====== */
.container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}
.container-wide { max-width: 1600px; margin: 0 auto; padding: 0 20px; }

/* ====== Tabs / Pills ====== */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--surface);
  padding: 3px;
  border-radius: 7px;
  border: 1px solid var(--border);
}
.tab {
  padding: 6px 13px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-2);
  border-radius: 5px;
  transition: all .15s;
  white-space: nowrap;
}
.tab:hover { color: var(--text-0); }
.tab.active {
  background: var(--bg-3);
  color: var(--text-0);
  box-shadow: 0 1px 2px rgba(0,0,0,.3);
}

.tab-line {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  scrollbar-width: none;
}
.tab-line::-webkit-scrollbar { display: none; }
.tab-line .tab-l {
  padding: 11px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-2);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  cursor: pointer;
  white-space: nowrap;
  transition: all .15s;
}
.tab-line .tab-l:hover { color: var(--text-0); }
.tab-line .tab-l.active {
  color: var(--text-0);
  border-color: var(--accent);
}

/* ====== Badges & Chips ====== */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.badge-up { color: var(--green-bright); background: var(--green-soft); }
.badge-down { color: var(--red-bright); background: var(--red-soft); }
.badge-neutral { color: var(--text-2); background: var(--surface); }
.badge-platinum { color: #d6e4ff; background: linear-gradient(135deg, #2e3a52, #1a2238); border: 1px solid #3a4a6a; }
.badge-gold { color: #2a1f00; background: linear-gradient(135deg, #f5c84c, #c89427); }
.badge-tier {
  padding: 4px 10px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.up { color: var(--green-bright); }
.down { color: var(--red-bright); }

/* ====== Cards & Sections ====== */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 18px;
}
.section { padding: 40px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 18px;
  gap: 16px;
  flex-wrap: wrap;
}
.section-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-0);
}
.section-sub { color: var(--text-2); font-size: 13px; margin-top: 4px; }

/* ====== Tables ====== */
.tbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.tbl th {
  text-align: left;
  font-weight: 500;
  color: var(--text-3);
  font-size: 11.5px;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}
.tbl td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-1);
}
.tbl tr:hover td { background: rgba(255,255,255,.025); }
.tbl td.num, .tbl th.num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl tbody tr:last-child td { border-bottom: none; }

.t-symbol {
  display: flex; align-items: center; gap: 10px;
  font-weight: 600;
}
.t-icon {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--bg-3);
  display: grid; place-items: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-0);
  flex-shrink: 0;
  border: 1px solid var(--border);
}
.t-icon.bg-blue { background: linear-gradient(135deg, #2962FF, #4d7fff); border: none; color: #fff; }
.t-icon.bg-green { background: linear-gradient(135deg, #00d4a8, #00b394); border: none; color: #001712; }
.t-icon.bg-red { background: linear-gradient(135deg, #ff6b78, #d63f4d); border: none; color: #fff; }
.t-icon.bg-orange { background: linear-gradient(135deg, #ff9d3a, #f57c00); border: none; color: #fff; }
.t-icon.bg-purple { background: linear-gradient(135deg, #b18bff, #7c5cff); border: none; color: #fff; }
.t-icon.bg-gold { background: linear-gradient(135deg, #f5c84c, #c89427); border: none; color: #2a1f00; }
.t-icon.bg-teal { background: linear-gradient(135deg, #00c6c6, #008b8b); border: none; color: #fff; }
.t-icon.bg-pink { background: linear-gradient(135deg, #f06292, #c94570); border: none; color: #fff; }

.t-meta { display: flex; flex-direction: column; }
.t-meta .t-name { font-size: 11.5px; color: var(--text-3); font-weight: 400; }

/* ====== Sparklines ====== */
.spark { width: 88px; height: 28px; display: inline-block; vertical-align: middle; }
.spark-up path.line { stroke: var(--green-bright); }
.spark-up path.fill { fill: url(#gradUp); }
.spark-down path.line { stroke: var(--red-bright); }
.spark-down path.fill { fill: url(#gradDown); }

/* ====== Hero ====== */
.hero {
  position: relative;
  padding: 80px 0 60px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 20% 0%, rgba(41,98,255,.18), transparent 50%),
    radial-gradient(ellipse at 80% 30%, rgba(0,198,198,.12), transparent 50%),
    var(--bg-0);
}
.hero::before {
  content: "";
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 60px 60px;
  mask: radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%);
  -webkit-mask: radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%);
  pointer-events: none;
}
.hero-inner { position: relative; display: grid; grid-template-columns: 1.1fr 1fr; gap: 50px; align-items: center; }
.hero h1 {
  font-size: 56px;
  line-height: 1.04;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--text-0);
  margin-bottom: 18px;
}
.hero h1 .accent {
  background: linear-gradient(120deg, var(--accent-2), var(--teal));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p.lead {
  font-size: 17px;
  color: var(--text-2);
  max-width: 560px;
  margin-bottom: 28px;
  line-height: 1.6;
}
.hero-ctas { display: flex; gap: 12px; margin-bottom: 26px; }
.hero-meta { display: flex; gap: 28px; color: var(--text-3); font-size: 13px; }
.hero-meta strong { color: var(--text-0); font-weight: 600; }
.hero-visual {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 4/3;
}
.hv-toolbar {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-2);
}
.hv-toolbar .price { font-size: 22px; font-weight: 700; color: var(--text-0); }
.hv-chart { height: calc(100% - 50px); position: relative; }

/* ====== Footer ====== */
.footer {
  background: var(--bg-1);
  border-top: 1px solid var(--border);
  padding: 50px 0 28px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-0);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 14px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 9px; }
.footer-col a {
  color: var(--text-2);
  font-size: 13px;
  transition: color .15s;
}
.footer-col a:hover { color: var(--text-0); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-3);
  font-size: 12px;
  flex-wrap: wrap;
  gap: 12px;
}

/* ====== Market Summary (home) ====== */
.summary-bar {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  overflow: hidden;
}
.summary-cell {
  padding: 14px 16px;
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.summary-cell:last-child { border-right: none; }
.summary-cell .label {
  font-size: 12px;
  color: var(--text-3);
  font-weight: 500;
}
.summary-cell .value {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-0);
  font-variant-numeric: tabular-nums;
}

/* ====== Idea Cards ====== */
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.idea-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all .2s;
  display: flex;
  flex-direction: column;
}
.idea-card:hover { transform: translateY(-2px); border-color: var(--border-strong); box-shadow: var(--shadow-md); }
.idea-thumb {
  aspect-ratio: 16/10;
  position: relative;
  background: var(--bg-2);
  overflow: hidden;
}
.idea-thumb svg { width: 100%; height: 100%; display: block; }
.idea-thumb .badge-bias {
  position: absolute; top: 10px; left: 10px;
  font-size: 10.5px;
  padding: 3px 8px;
  letter-spacing: .04em;
}
.idea-thumb .ticker-tag {
  position: absolute; top: 10px; right: 10px;
  background: rgba(0,0,0,.6);
  backdrop-filter: blur(8px);
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-0);
}
.idea-body { padding: 14px 14px 12px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.idea-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-0);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.idea-author {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px;
  color: var(--text-2);
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.avatar {
  width: 22px; height: 22px;
  border-radius: 50%;
  background: var(--accent);
  display: grid; place-items: center;
  font-size: 10px;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}
.idea-stats {
  display: flex; gap: 12px;
  font-size: 11.5px;
  color: var(--text-3);
}

/* ====== Chart page ====== */
.chart-app {
  display: grid;
  grid-template-columns: 56px 1fr 320px;
  height: calc(100vh - var(--header-h));
}
.chart-tools {
  background: var(--bg-1);
  border-right: 1px solid var(--border);
  padding: 8px 0;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.tool-btn {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  transition: all .15s;
}
.tool-btn:hover { background: var(--surface); color: var(--text-0); }
.tool-btn.active { background: var(--accent-soft); color: var(--accent-2); }
.tool-divider { width: 24px; height: 1px; background: var(--border); margin: 6px 0; }

.chart-main { display: flex; flex-direction: column; min-width: 0; background: var(--bg-1); }
.chart-toolbar {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-1);
  flex-wrap: wrap;
}
.symbol-picker {
  display: flex; align-items: center; gap: 10px;
  padding: 6px 12px;
  border-radius: 6px;
  background: var(--surface);
  border: 1px solid var(--border);
  cursor: pointer;
}
.symbol-picker:hover { border-color: var(--border-strong); }
.symbol-picker .sym {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-0);
}
.tf-group { display: flex; gap: 1px; background: var(--surface); border: 1px solid var(--border); border-radius: 5px; padding: 1px; }
.tf-btn {
  padding: 5px 10px;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-2);
  border-radius: 4px;
  font-variant-numeric: tabular-nums;
}
.tf-btn:hover { color: var(--text-0); }
.tf-btn.active { background: var(--accent); color: white; }
.toolbar-divider { width: 1px; height: 22px; background: var(--border); }

.chart-canvas { flex: 1; position: relative; min-height: 360px; background: var(--bg-1); }
.chart-svg { width: 100%; height: 100%; display: block; }

.chart-bottom {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid var(--border);
  background: var(--bg-1);
  max-height: 320px;
  overflow: hidden;
}
.detail-block {
  padding: 16px 18px;
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.detail-block:last-child { border-right: none; }

.watchlist-side {
  background: var(--bg-1);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.wl-head {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
  font-size: 12px;
  color: var(--text-2);
  font-weight: 600;
}
.wl-content { flex: 1; overflow-y: auto; }
.wl-cat {
  border-bottom: 1px solid var(--border);
}
.wl-cat-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 9px 12px;
  background: var(--bg-2);
  cursor: pointer;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-2);
  text-transform: uppercase;
  letter-spacing: .04em;
  user-select: none;
}
.wl-cat-head .chev { transition: transform .2s; }
.wl-cat.open .wl-cat-head .chev { transform: rotate(90deg); }
.wl-cat-body { display: none; }
.wl-cat.open .wl-cat-body { display: block; }
.wl-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  font-size: 12.5px;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.wl-row:hover { background: rgba(255,255,255,.03); }
.wl-row .sym { font-weight: 600; color: var(--text-0); }
.wl-row .last { color: var(--text-1); text-align: right; }
.wl-row .chg { font-size: 11.5px; font-weight: 600; text-align: right; min-width: 56px; }

/* ====== Stat grid ====== */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 12px;
}
.stat-tile {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 12px;
}
.stat-tile .label { font-size: 11.5px; color: var(--text-3); }
.stat-tile .val { font-size: 16px; font-weight: 700; color: var(--text-0); margin-top: 4px; font-variant-numeric: tabular-nums; }
.stat-tile .sub { font-size: 11px; color: var(--text-2); margin-top: 2px; }

/* ====== Markets page sections ====== */
.markets-tabs {
  position: sticky;
  top: var(--header-h);
  z-index: 30;
  background: var(--bg-0);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
}

.market-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
}
.movers-list { display: flex; flex-direction: column; gap: 8px; }
.mover-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 12px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 7px;
}
.mover-row .name { font-size: 13px; font-weight: 500; color: var(--text-0); }
.mover-row .sub { font-size: 11.5px; color: var(--text-3); }

/* ====== Brokers ====== */
.broker-card {
  display: grid;
  grid-template-columns: 200px 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 20px 22px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 12px;
  transition: all .15s;
}
.broker-card:hover { border-color: var(--border-strong); transform: translateY(-1px); }
.broker-brand { display: flex; align-items: center; gap: 14px; }
.broker-logo {
  width: 50px; height: 50px;
  border-radius: 9px;
  display: grid; place-items: center;
  font-size: 14px;
  font-weight: 800;
  color: #fff;
  flex-shrink: 0;
}
.broker-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-0);
}
.broker-details {
  display: flex;
  align-items: center;
  gap: 28px;
}
.broker-stat .label { font-size: 11px; color: var(--text-3); text-transform: uppercase; letter-spacing: .04em; }
.broker-stat .val { font-size: 14px; font-weight: 600; color: var(--text-0); margin-top: 2px; }
.broker-rating { display: flex; align-items: center; gap: 8px; }
.rating-num {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-0);
  line-height: 1;
}
.rating-stars { color: var(--gold); font-size: 12px; letter-spacing: 1px; }
.broker-promo {
  background: var(--accent-soft);
  color: var(--accent-2);
  padding: 5px 10px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
  border: 1px solid rgba(41,98,255,.25);
}

/* ====== Stats banner ====== */
.stats-banner {
  background: linear-gradient(120deg, var(--bg-2), var(--bg-3));
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 36px 40px;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 30px;
  margin: 32px 0;
}
.stat-big .num { font-size: 46px; font-weight: 800; color: var(--text-0); letter-spacing: -.02em; line-height: 1; }
.stat-big .num .accent-blue { color: var(--accent-2); }
.stat-big .label { font-size: 13px; color: var(--text-2); margin-top: 8px; }

/* ====== Generic flex utilities ====== */
.row { display: flex; align-items: center; gap: 8px; }
.between { justify-content: space-between; }
.gap-12 { gap: 12px; } .gap-16 { gap: 16px; } .gap-20 { gap: 20px; }
.flex-1 { flex: 1; }
.muted { color: var(--text-3); }
.txt-0 { color: var(--text-0); }
.txt-1 { color: var(--text-1); }
.txt-2 { color: var(--text-2); }
.fw-7 { font-weight: 700; }
.fs-12 { font-size: 12px; } .fs-13 { font-size: 13px; } .fs-14 { font-size: 14px; }
.mt-8 { margin-top: 8px; } .mt-12 { margin-top: 12px; } .mt-16 { margin-top: 16px; } .mt-24 { margin-top: 24px; }
.mb-12 { margin-bottom: 12px; } .mb-16 { margin-bottom: 16px; } .mb-24 { margin-bottom: 24px; }

/* ====== Page hero (smaller) ====== */
.page-hero {
  padding: 50px 0 30px;
  background:
    radial-gradient(ellipse at 30% 0%, rgba(41,98,255,.18), transparent 60%),
    var(--bg-0);
  border-bottom: 1px solid var(--border);
}
.page-hero h1 {
  font-size: 38px;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--text-0);
  margin-bottom: 8px;
}
.page-hero p { color: var(--text-2); font-size: 15px; max-width: 640px; }

/* ====== Pagination ====== */
.pager {
  display: flex; justify-content: center; gap: 6px; margin: 32px 0;
}
.pager button {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 600;
  border: 1px solid var(--border);
  background: var(--surface);
}
.pager button:hover { color: var(--text-0); border-color: var(--border-strong); }
.pager button.active { background: var(--accent); color: white; border-color: var(--accent); }

/* ====== Trending list ====== */
.trending-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.trend-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px;
  display: flex; flex-direction: column; gap: 8px;
  transition: all .15s;
}
.trend-card:hover { border-color: var(--border-strong); }
.trend-head { display: flex; align-items: center; justify-content: space-between; }
.trend-card .price { font-size: 18px; font-weight: 700; color: var(--text-0); font-variant-numeric: tabular-nums; }

/* ====== Indicator/strategy cards ====== */
.ind-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.ind-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
  display: flex; gap: 12px;
}
.ind-icon {
  width: 40px; height: 40px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent-2);
  display: grid; place-items: center;
  flex-shrink: 0;
}
.ind-card h4 { font-size: 14px; font-weight: 600; color: var(--text-0); margin-bottom: 3px; }
.ind-card p { font-size: 12px; color: var(--text-2); line-height: 1.5; }

/* ====== Stories ====== */
.stories-grid { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 16px; }
.story-feature {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  min-height: 360px;
  display: flex; flex-direction: column;
}
.story-feature .sf-img { aspect-ratio: 16/9; background: linear-gradient(135deg, #1a3354, #2a1a4d); }
.story-feature .sf-body { padding: 18px; flex: 1; display: flex; flex-direction: column; gap: 10px; }
.story-feature h3 { font-size: 19px; font-weight: 700; color: var(--text-0); line-height: 1.25; }
.story-side {
  display: flex; flex-direction: column; gap: 12px;
}
.story-row {
  display: flex; gap: 10px;
  padding: 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.story-row .sr-img {
  width: 80px; height: 64px;
  border-radius: 6px;
  flex-shrink: 0;
  background: var(--bg-3);
}
.story-row h5 { font-size: 13px; color: var(--text-0); font-weight: 600; line-height: 1.3; }
.story-row .meta { font-size: 11px; color: var(--text-3); margin-top: 4px; }

/* ====== Mini chart styles ====== */
.mini-chart-cell {
  display: flex; align-items: center; gap: 6px;
}

/* ====== Stocks tabs row ====== */
.stocks-flex {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 16px;
}

/* Responsive */
@media (max-width: 1280px) {
  .summary-bar { grid-template-columns: repeat(3, 1fr); }
  .summary-cell:nth-child(3) { border-right: none; }
  .ideas-grid { grid-template-columns: repeat(3, 1fr); }
  .ind-grid { grid-template-columns: repeat(2, 1fr); }
  .trending-list { grid-template-columns: repeat(3, 1fr); }
  .stocks-flex { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1.2fr repeat(3, 1fr); }
  .chart-app { grid-template-columns: 56px 1fr 280px; }
}
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero h1 { font-size: 40px; }
  .ideas-grid, .trending-list { grid-template-columns: repeat(2, 1fr); }
  .stories-grid { grid-template-columns: 1fr; }
  .stats-banner { grid-template-columns: 1fr; gap: 20px; }
  .header-search { display: none; }
  .main-nav { gap: 0; overflow-x: auto; }
  .ind-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .stocks-flex { grid-template-columns: 1fr; }
  .market-grid { grid-template-columns: 1fr; }
  .broker-card { grid-template-columns: 1fr; gap: 14px; }
  .chart-app { grid-template-columns: 1fr; }
  .chart-tools, .watchlist-side { display: none; }
}
@media (max-width: 640px) {
  .hero h1 { font-size: 30px; }
  .summary-bar { grid-template-columns: 1fr 1fr; }
  .ideas-grid, .trending-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .container { padding: 0 14px; }
  .section { padding: 28px 0; }
}

raw_arguments.content:
/* ChartPulse — Trading Terminal Design System */
:root {
  --bg-0: #0a0a0f;
  --bg-1: #0f0f1a;
  --bg-2: #14142a;
  --bg-3: #1a1a2e;
  --bg-4: #1f1f38;
  --surface: #16162b;
  --surface-2: #1c1c34;
  --border: #252544;
  --border-strong: #33335a;
  --text-0: #f5f6ff;
  --text-1: #d6d8ee;
  --text-2: #9da0c2;
  --text-3: #6c6e8f;
  --accent: #2962FF;
  --accent-2: #4d7fff;
  --accent-soft: rgba(41, 98, 255, 0.12);
  --green: #22ab94;
  --green-bright: #26d4a8;
  --green-soft: rgba(38, 212, 168, 0.12);
  --red: #F7525F;
  --red-bright: #ff6b78;
  --red-soft: rgba(247, 82, 95, 0.12);
  --amber: #ffb547;
  --purple: #b18bff;
  --teal: #00c6c6;
  --gold: #d4a72c;
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 12px 40px rgba(0, 0, 0, 0.6);
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;
  --radius-xl: 14px;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', Menlo, Consolas, monospace;
  --header-h: 56px;
  --subnav-h: 44px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg-0);
  color: var(--text-1);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'cv11', 'ss01';
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
input, select { font-family: inherit; }

/* Numerics — tabular for tables */
.num, td.num, .price, .change {
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum';
}

/* ====== Header / Top Nav ====== */
.app-header {
  position: sticky;
  top: 0;
  z-index: 50;
  height: var(--header-h);
  background: rgba(15, 15, 26, 0.92);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 20px;
  gap: 24px;
}
.logo {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 700;
  font-size: 16px;
  color: var(--text-0);
  letter-spacing: -0.01em;
}
.logo-mark {
  width: 26px;
  height: 26px;
  background: linear-gradient(135deg, var(--accent), var(--teal));
  border-radius: 7px;
  display: grid;
  place-items: center;
  color: white;
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.main-nav a {
  padding: 8px 13px;
  border-radius: 6px;
  color: var(--text-2);
  font-weight: 500;
  font-size: 13.5px;
  transition: all .15s;
}
.main-nav a:hover { color: var(--text-0); background: var(--surface); }
.main-nav a.active { color: var(--text-0); background: var(--surface); }
.header-search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 10px;
  width: 240px;
  color: var(--text-3);
  font-size: 13px;
}
.header-search input {
  background: none;
  border: none;
  color: var(--text-0);
  outline: none;
  flex: 1;
  font-size: 13px;
}
.header-actions { display: flex; align-items: center; gap: 8px; }
.btn-icon {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  transition: all .15s;
}
.btn-icon:hover { background: var(--surface); color: var(--text-0); }

/* ====== Buttons ====== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  transition: all .15s;
  border: 1px solid transparent;
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: white;
}
.btn-primary:hover { background: var(--accent-2); }
.btn-secondary {
  background: var(--surface);
  color: var(--text-0);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--surface-2); border-color: var(--accent); }
.btn-ghost { color: var(--text-1); }
.btn-ghost:hover { background: var(--surface); }
.btn-lg { padding: 12px 22px; font-size: 14px; }
.btn-sm { padding: 6px 11px; font-size: 12px; border-radius: 5px; }

/* ====== Common Layout ====== */
.container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}
.container-wide { max-width: 1600px; margin: 0 auto; padding: 0 20px; }

/* ====== Tabs / Pills ====== */
.tabs {
  display: flex;
  gap: 2px;
  background: var(--surface);
  padding: 3px;
  border-radius: 7px;
  border: 1px solid var(--border);
}
.tab {
  padding: 6px 13px;
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-2);
  border-radius: 5px;
  transition: all .15s;
  white-space: nowrap;
}
.tab:hover { color: var(--text-0); }
.tab.active {
  background: var(--bg-3);
  color: var(--text-0);
  box-shadow: 0 1px 2px rgba(0,0,0,.3);
}

.tab-line {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
  scrollbar-width: none;
}
.tab-line::-webkit-scrollbar { display: none; }
.tab-line .tab-l {
  padding: 11px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-2);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  cursor: pointer;
  white-space: nowrap;
  transition: all .15s;
}
.tab-line .tab-l:hover { color: var(--text-0); }
.tab-line .tab-l.active {
  color: var(--text-0);
  border-color: var(--accent);
}

/* ====== Badges & Chips ====== */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 4px;
  font-size: 11.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.badge-up { color: var(--green-bright); background: var(--green-soft); }
.badge-down { color: var(--red-bright); background: var(--red-soft); }
.badge-neutral { color: var(--text-2); background: var(--surface); }
.badge-platinum { color: #d6e4ff; background: linear-gradient(135deg, #2e3a52, #1a2238); border: 1px solid #3a4a6a; }
.badge-gold { color: #2a1f00; background: linear-gradient(135deg, #f5c84c, #c89427); }
.badge-tier {
  padding: 4px 10px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.up { color: var(--green-bright); }
.down { color: var(--red-bright); }

/* ====== Cards & Sections ====== */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 18px;
}
.section { padding: 40px 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  margin-bottom: 18px;
  gap: 16px;
  flex-wrap: wrap;
}
.section-title {
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text-0);
}
.section-sub { color: var(--text-2); font-size: 13px; margin-top: 4px; }

/* ====== Tables ====== */
.tbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.tbl th {
  text-align: left;
  font-weight: 500;
  color: var(--text-3);
  font-size: 11.5px;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}
.tbl td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-1);
}
.tbl tr:hover td { background: rgba(255,255,255,.025); }
.tbl td.num, .tbl th.num { text-align: right; font-variant-numeric: tabular-nums; }
.tbl tbody tr:last-child td { border-bottom: none; }

.t-symbol {
  display: flex; align-items: center; gap: 10px;
  font-weight: 600;
}
.t-icon {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--bg-3);
  display: grid; place-items: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-0);
  flex-shrink: 0;
  border: 1px solid var(--border);
}
.t-icon.bg-blue { background: linear-gradient(135deg, #2962FF, #4d7fff); border: none; color: #fff; }
.t-icon.bg-green { background: linear-gradient(135deg, #00d4a8, #00b394); border: none; color: #001712; }
.t-icon.bg-red { background: linear-gradient(135deg, #ff6b78, #d63f4d); border: none; color: #fff; }
.t-icon.bg-orange { background: linear-gradient(135deg, #ff9d3a, #f57c00); border: none; color: #fff; }
.t-icon.bg-purple { background: linear-gradient(135deg, #b18bff, #7c5cff); border: none; color: #fff; }
.t-icon.bg-gold { background: linear-gradient(135deg, #f5c84c, #c89427); border: none; color: #2a1f00; }
.t-icon.bg-teal { background: linear-gradient(135deg, #00c6c6, #008b8b); border: none; color: #fff; }
.t-icon.bg-pink { background: linear-gradient(135deg, #f06292, #c94570); border: none; color: #fff; }

.t-meta { display: flex; flex-direction: column; }
.t-meta .t-name { font-size: 11.5px; color: var(--text-3); font-weight: 400; }

/* ====== Sparklines ====== */
.spark { width: 88px; height: 28px; display: inline-block; vertical-align: middle; }
.spark-up path.line { stroke: var(--green-bright); }
.spark-up path.fill { fill: url(#gradUp); }
.spark-down path.line { stroke: var(--red-bright); }
.spark-down path.fill { fill: url(#gradDown); }

/* ====== Hero ====== */
.hero {
  position: relative;
  padding: 80px 0 60px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 20% 0%, rgba(41,98,255,.18), transparent 50%),
    radial-gradient(ellipse at 80% 30%, rgba(0,198,198,.12), transparent 50%),
    var(--bg-0);
}
.hero::before {
  content: "";
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 60px 60px;
  mask: radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%);
  -webkit-mask: radial-gradient(ellipse at 50% 30%, black 30%, transparent 70%);
  pointer-events: none;
}
.hero-inner { position: relative; display: grid; grid-template-columns: 1.1fr 1fr; gap: 50px; align-items: center; }
.hero h1 {
  font-size: 56px;
  line-height: 1.04;
  font-weight: 700;
  letter-spacing: -0.025em;
  color: var(--text-0);
  margin-bottom: 18px;
}
.hero h1 .accent {
  background: linear-gradient(120deg, var(--accent-2), var(--teal));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.hero p.lead {
  font-size: 17px;
  color: var(--text-2);
  max-width: 560px;
  margin-bottom: 28px;
  line-height: 1.6;
}
.hero-ctas { display: flex; gap: 12px; margin-bottom: 26px; }
.hero-meta { display: flex; gap: 28px; color: var(--text-3); font-size: 13px; }
.hero-meta strong { color: var(--text-0); font-weight: 600; }
.hero-visual {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  aspect-ratio: 4/3;
}
.hv-toolbar {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-2);
}
.hv-toolbar .price { font-size: 22px; font-weight: 700; color: var(--text-0); }
.hv-chart { height: calc(100% - 50px); position: relative; }

/* ====== Footer ====== */
.footer {
  background: var(--bg-1);
  border-top: 1px solid var(--border);
  padding: 50px 0 28px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer-col h5 {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-0);
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: 14px;
}
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 9px; }
.footer-col a {
  color: var(--text-2);
  font-size: 13px;
  transition: color .15s;
}
.footer-col a:hover { color: var(--text-0); }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 22px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-3);
  font-size: 12px;
  flex-wrap: wrap;
  gap: 12px;
}

/* ====== Market Summary (home) ====== */
.summary-bar {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  overflow: hidden;
}
.summary-cell {
  padding: 14px 16px;
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.summary-cell:last-child { border-right: none; }
.summary-cell .label {
  font-size: 12px;
  color: var(--text-3);
  font-weight: 500;
}
.summary-cell .value {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-0);
  font-variant-numeric: tabular-nums;
}

/* ====== Idea Cards ====== */
.ideas-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.idea-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all .2s;
  display: flex;
  flex-direction: column;
}
.idea-card:hover { transform: translateY(-2px); border-color: var(--border-strong); box-shadow: var(--shadow-md); }
.idea-thumb {
  aspect-ratio: 16/10;
  position: relative;
  background: var(--bg-2);
  overflow: hidden;
}
.idea-thumb svg { width: 100%; height: 100%; display: block; }
.idea-thumb .badge-bias {
  position: absolute; top: 10px; left: 10px;
  font-size: 10.5px;
  padding: 3px 8px;
  letter-spacing: .04em;
}
.idea-thumb .ticker-tag {
  position: absolute; top: 10px; right: 10px;
  background: rgba(0,0,0,.6);
  backdrop-filter: blur(8px);
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 700;
  color: var(--text-0);
}
.idea-body { padding: 14px 14px 12px; flex: 1; display: flex; flex-direction: column; gap: 8px; }
.idea-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-0);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.idea-author {
  display: flex; align-items: center; gap: 8px;
  font-size: 12px;
  color: var(--text-2);
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.avatar {
  width: 22px; height: 22px;
  border-radius: 50%;
  background: var(--accent);
  display: grid; place-items: center;
  font-size: 10px;
  font-weight: 700;
  color: white;
  flex-shrink: 0;
}
.idea-stats {
  display: flex; gap: 12px;
  font-size: 11.5px;
  color: var(--text-3);
}

/* ====== Chart page ====== */
.chart-app {
  display: grid;
  grid-template-columns: 56px 1fr 320px;
  height: calc(100vh - var(--header-h));
}
.chart-tools {
  background: var(--bg-1);
  border-right: 1px solid var(--border);
  padding: 8px 0;
  display: flex; flex-direction: column; align-items: center; gap: 4px;
}
.tool-btn {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  transition: all .15s;
}
.tool-btn:hover { background: var(--surface); color: var(--text-0); }
.tool-btn.active { background: var(--accent-soft); color: var(--accent-2); }
.tool-divider { width: 24px; height: 1px; background: var(--border); margin: 6px 0; }

.chart-main { display: flex; flex-direction: column; min-width: 0; background: var(--bg-1); }
.chart-toolbar {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-1);
  flex-wrap: wrap;
}
.symbol-picker {
  display: flex; align-items: center; gap: 10px;
  padding: 6px 12px;
  border-radius: 6px;
  background: var(--surface);
  border: 1px solid var(--border);
  cursor: pointer;
}
.symbol-picker:hover { border-color: var(--border-strong); }
.symbol-picker .sym {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-0);
}
.tf-group { display: flex; gap: 1px; background: var(--surface); border: 1px solid var(--border); border-radius: 5px; padding: 1px; }
.tf-btn {
  padding: 5px 10px;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-2);
  border-radius: 4px;
  font-variant-numeric: tabular-nums;
}
.tf-btn:hover { color: var(--text-0); }
.tf-btn.active { background: var(--accent); color: white; }
.toolbar-divider { width: 1px; height: 22px; background: var(--border); }

.chart-canvas { flex: 1; position: relative; min-height: 360px; background: var(--bg-1); }
.chart-svg { width: 100%; height: 100%; display: block; }

.chart-bottom {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border-top: 1px solid var(--border);
  background: var(--bg-1);
  max-height: 320px;
  overflow: hidden;
}
.detail-block {
  padding: 16px 18px;
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.detail-block:last-child { border-right: none; }

.watchlist-side {
  background: var(--bg-1);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.wl-head {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
  font-size: 12px;
  color: var(--text-2);
  font-weight: 600;
}
.wl-content { flex: 1; overflow-y: auto; }
.wl-cat {
  border-bottom: 1px solid var(--border);
}
.wl-cat-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 9px 12px;
  background: var(--bg-2);
  cursor: pointer;
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-2);
  text-transform: uppercase;
  letter-spacing: .04em;
  user-select: none;
}
.wl-cat-head .chev { transition: transform .2s; }
.wl-cat.open .wl-cat-head .chev { transform: rotate(90deg); }
.wl-cat-body { display: none; }
.wl-cat.open .wl-cat-body { display: block; }
.wl-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  font-size: 12.5px;
  cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.wl-row:hover { background: rgba(255,255,255,.03); }
.wl-row .sym { font-weight: 600; color: var(--text-0); }
.wl-row .last { color: var(--text-1); text-align: right; }
.wl-row .chg { font-size: 11.5px; font-weight: 600; text-align: right; min-width: 56px; }

/* ====== Stat grid ====== */
.stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 12px;
}
.stat-tile {
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 12px;
}
.stat-tile .label { font-size: 11.5px; color: var(--text-3); }
.stat-tile .val { font-size: 16px; font-weight: 700; color: var(--text-0); margin-top: 4px; font-variant-numeric: tabular-nums; }
.stat-tile .sub { font-size: 11px; color: var(--text-2); margin-top: 2px; }

/* ====== Markets page sections ====== */
.markets-tabs {
  position: sticky;
  top: var(--header-h);
  z-index: 30;
  background: var(--bg-0);
  border-bottom: 1px solid var(--border);
  padding: 0 24px;
}

.market-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 20px;
}
.movers-list { display: flex; flex-direction: column; gap: 8px; }
.mover-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 10px 12px;
  background: var(--bg-2);
  border: 1px solid var(--border);
  border-radius: 7px;
}
.mover-row .name { font-size: 13px; font-weight: 500; color: var(--text-0); }
.mover-row .sub { font-size: 11.5px; color: var(--text-3); }

/* ====== Brokers ====== */
.broker-card {
  display: grid;
  grid-template-columns: 200px 1fr auto;
  align-items: center;
  gap: 24px;
  padding: 20px 22px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  margin-bottom: 12px;
  transition: all .15s;
}
.broker-card:hover { border-color: var(--border-strong); transform: translateY(-1px); }
.broker-brand { display: flex; align-items: center; gap: 14px; }
.broker-logo {
  width: 50px; height: 50px;
  border-radius: 9px;
  display: grid; place-items: center;
  font-size: 14px;
  font-weight: 800;
  color: #fff;
  flex-shrink: 0;
}
.broker-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-0);
}
.broker-details {
  display: flex;
  align-items: center;
  gap: 28px;
}
.broker-stat .label { font-size: 11px; color: var(--text-3); text-transform: uppercase; letter-spacing: .04em; }
.broker-stat .val { font-size: 14px; font-weight: 600; color: var(--text-0); margin-top: 2px; }
.broker-rating { display: flex; align-items: center; gap: 8px; }
.rating-num {
  font-size: 22px;
  font-weight: 700;
  color: var(--text-0);
  line-height: 1;
}
.rating-stars { color: var(--gold); font-size: 12px; letter-spacing: 1px; }
.broker-promo {
  background: var(--accent-soft);
  color: var(--accent-2);
  padding: 5px 10px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
  border: 1px solid rgba(41,98,255,.25);
}

/* ====== Stats banner ====== */
.stats-banner {
  background: linear-gradient(120deg, var(--bg-2), var(--bg-3));
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 36px 40px;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 30px;
  margin: 32px 0;
}
.stat-big .num { font-size: 46px; font-weight: 800; color: var(--text-0); letter-spacing: -.02em; line-height: 1; }
.stat-big .num .accent-blue { color: var(--accent-2); }
.stat-big .label { font-size: 13px; color: var(--text-2); margin-top: 8px; }

/* ====== Generic flex utilities ====== */
.row { display: flex; align-items: center; gap: 8px; }
.between { justify-content: space-between; }
.gap-12 { gap: 12px; } .gap-16 { gap: 16px; } .gap-20 { gap: 20px; }
.flex-1 { flex: 1; }
.muted { color: var(--text-3); }
.txt-0 { color: var(--text-0); }
.txt-1 { color: var(--text-1); }
.txt-2 { color: var(--text-2); }
.fw-7 { font-weight: 700; }
.fs-12 { font-size: 12px; } .fs-13 { font-size: 13px; } .fs-14 { font-size: 14px; }
.mt-8 { margin-top: 8px; } .mt-12 { margin-top: 12px; } .mt-16 { margin-top: 16px; } .mt-24 { margin-top: 24px; }
.mb-12 { margin-bottom: 12px; } .mb-16 { margin-bottom: 16px; } .mb-24 { margin-bottom: 24px; }

/* ====== Page hero (smaller) ====== */
.page-hero {
  padding: 50px 0 30px;
  background:
    radial-gradient(ellipse at 30% 0%, rgba(41,98,255,.18), transparent 60%),
    var(--bg-0);
  border-bottom: 1px solid var(--border);
}
.page-hero h1 {
  font-size: 38px;
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--text-0);
  margin-bottom: 8px;
}
.page-hero p { color: var(--text-2); font-size: 15px; max-width: 640px; }

/* ====== Pagination ====== */
.pager {
  display: flex; justify-content: center; gap: 6px; margin: 32px 0;
}
.pager button {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 6px;
  color: var(--text-2);
  font-size: 13px;
  font-weight: 600;
  border: 1px solid var(--border);
  background: var(--surface);
}
.pager button:hover { color: var(--text-0); border-color: var(--border-strong); }
.pager button.active { background: var(--accent); color: white; border-color: var(--accent); }

/* ====== Trending list ====== */
.trending-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}
.trend-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 14px;
  display: flex; flex-direction: column; gap: 8px;
  transition: all .15s;
}
.trend-card:hover { border-color: var(--border-strong); }
.trend-head { display: flex; align-items: center; justify-content: space-between; }
.trend-card .price { font-size: 18px; font-weight: 700; color: var(--text-0); font-variant-numeric: tabular-nums; }

/* ====== Indicator/strategy cards ====== */
.ind-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
.ind-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
  display: flex; gap: 12px;
}
.ind-icon {
  width: 40px; height: 40px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent-2);
  display: grid; place-items: center;
  flex-shrink: 0;
}
.ind-card h4 { font-size: 14px; font-weight: 600; color: var(--text-0); margin-bottom: 3px; }
.ind-card p { font-size: 12px; color: var(--text-2); line-height: 1.5; }

/* ====== Stories ====== */
.stories-grid { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 16px; }
.story-feature {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  min-height: 360px;
  display: flex; flex-direction: column;
}
.story-feature .sf-img { aspect-ratio: 16/9; background: linear-gradient(135deg, #1a3354, #2a1a4d); }
.story-feature .sf-body { padding: 18px; flex: 1; display: flex; flex-direction: column; gap: 10px; }
.story-feature h3 { font-size: 19px; font-weight: 700; color: var(--text-0); line-height: 1.25; }
.story-side {
  display: flex; flex-direction: column; gap: 12px;
}
.story-row {
  display: flex; gap: 10px;
  padding: 10px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.story-row .sr-img {
  width: 80px; height: 64px;
  border-radius: 6px;
  flex-shrink: 0;
  background: var(--bg-3);
}
.story-row h5 { font-size: 13px; color: var(--text-0); font-weight: 600; line-height: 1.3; }
.story-row .meta { font-size: 11px; color: var(--text-3); margin-top: 4px; }

/* ====== Mini chart styles ====== */
.mini-chart-cell {
  display: flex; align-items: center; gap: 6px;
}

/* ====== Stocks tabs row ====== */
.stocks-flex {
  display: grid;
  grid-template-columns: 1.6fr 1fr 1fr;
  gap: 16px;
}

/* Responsive */
@media (max-width: 1280px) {
  .summary-bar { grid-template-columns: repeat(3, 1fr); }
  .summary-cell:nth-child(3) { border-right: none; }
  .ideas-grid { grid-template-columns: repeat(3, 1fr); }
  .ind-grid { grid-template-columns: repeat(2, 1fr); }
  .trending-list { grid-template-columns: repeat(3, 1fr); }
  .stocks-flex { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1.2fr repeat(3, 1fr); }
  .chart-app { grid-template-columns: 56px 1fr 280px; }
}
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero h1 { font-size: 40px; }
